sku,\'-\',-1)) = \'S\' OR upper(split_part(a.sku,\'-\',-1)) = \'30\' THEN \'S\' WHEN upper(split_part(a.sku,\'-\',-1)) = \'M\' OR upper(split_part(a.sku,\'-\',-1)) = \'32\' THEN \'M\' WHEN upper(split_part(a.sku,\'-\',-1)) = \'M\' OR upper(split_part(a.sku,\'-\',-1)) = \'32\' THEN \'M\' WHEN upper(split_part(a.sku,\'-\',-1)) = \'L\' OR upper(split_part(a.sku,\'-\',-1)) = \'34\' THEN \'L\' WHEN upper(split_part(a.sku,\'-\',-1)) = \'XL\' OR upper(split_part(a.sku,\'-\',-1)) = \'36\' THEN \'XL\' when upper(split_part(a.sku,\'-\',-1)) IN (\'XXL\', \'XXl\', \'2XL\', \'38\') THEN \'XXL\' WHEN upper(split_part(a.sku,\'-\',-1)) = \'3XL\' OR upper(split_part(a.sku,\'-\',-1)) = \'40\' THEN \'3XL\' WHEN upper(split_part(a.sku,\'-\',-1)) = \'4XL\' OR upper(split_part(a.sku,\'-\',-1)) = \'42\' then \'4XL\' WHEN upper(split_part(a.sku,\'-\',-1)) = \'5XL\' OR upper(split_part(a.sku,\'-\',-1)) = \'44\' then \'5XL\' WHEN upper(split_part(a.sku,\'-\',-1)) = \'6XL\' OR upper(split_part(a.sku,\'-\',-1)) = \'46\' THEN \'6XL\' WHEN upper(split_part(a.sku,\'-\',-1)) = \'7XL\' OR upper(split_part(a.sku,\'-\',-1)) = \'48\' THEN \'7XL\' WHEN upper(split_part(a.sku,\'-\',-1)) = \'8XL\' OR upper(split_part(a.sku,\'-\',-1)) = \'48\' THEN \'8XL\' end as size, c.product_type as category, c.product_tags as product_tags, b.original_price as price, d.cost_price, marketplace_mapped as channel, SUM(NULLIF(a.selling_price, 0)) AS gross_sales, SUM(NULLIF(a.shipping_quantity, 0)) AS gross_quantity, case when LOWER(marketplace_mapped) = \'ajio\' then SUM(NULLIF((b.original_price * a.shipping_quantity) - a.selling_price* 1.45, 0)) else SUM(NULLIF((b.original_price * a.shipping_quantity) - a.selling_price, 0)) end AS discount_amount, SUM(CASE WHEN new_customer_flag != \'Repeated\' THEN selling_price ELSE 0 END) AS new_customers_revenue, SUM(CASE WHEN new_customer_flag = \'Repeated\' THEN selling_price ELSE 0 END) AS repeat_customers_revenue, COUNT(DISTINCT CASE WHEN new_customer_flag != \'Repeated\' THEN customer_id ELSE NULL END) AS new_customers FROM snitch_db.maplemonk.unicommerce_fact_items_snitch a left join final_price b on upper(trim(a.sku_group)) = b.sku_group left join metafields c on a.sku_group = c.sku_group left join cost_price d on a.sku = d.sku and marketplace_mapped IN (\'Myntra\',\'SNAPMINT\',\'CRED\',\'DONOSHOP\',\'FYND\',\'AMAZON\',\'MYNTRA\',\'MENSXP\',\'NYKAA_FASHION\',\'AJIO\',\'FLIPKART\',\'NYKAA.COM\',\'NYKAA_FASHION\',\'POPCLUB\') AND name != \'FLIPKART_B2B_CUSTOM\' GROUP BY 1, 2, 3, 4, 5, 6, 7, 8, 9 ), stores_data AS ( SELECT order_date AS Date, \'Store\' AS type, upper(trim(a.sku_group)) as sku_group, case when upper(split_part(a.sku,\'-\',-1)) = \'XS\' OR upper(split_part(a.sku,\'-\',-1)) = \'28\' then \'XS\' WHEN upper(split_part(a.sku,\'-\',-1)) = \'S\' OR upper(split_part(a.sku,\'-\',-1)) = \'30\' THEN \'S\' WHEN upper(split_part(a.sku,\'-\',-1)) = \'M\' OR upper(split_part(a.sku,\'-\',-1)) = \'32\' THEN \'M\' WHEN upper(split_part(a.sku,\'-\',-1)) = \'M\' OR upper(split_part(a.sku,\'-\',-1)) = \'32\' THEN \'M\' WHEN upper(split_part(a.sku,\'-\',-1)) = \'L\' OR upper(split_part(a.sku,\'-\',-1)) = \'34\' THEN \'L\' WHEN upper(split_part(a.sku,\'-\',-1)) = \'XL\' OR upper(split_part(a.sku,\'-\',-1)) = \'36\' THEN \'XL\' when upper(split_part(a.sku,\'-\',-1)) IN (\'XXL\', \'XXl\', \'2XL\', \'38\') THEN \'XXL\' WHEN upper(split_part(a.sku,\'-\',-1)) = \'3XL\' OR upper(split_part(a.sku,\'-\',-1)) = \'40\' THEN \'3XL\' WHEN upper(split_part(a.sku,\'-\',-1)) = \'4XL\' OR upper(split_part(a.sku,\'-\',-1)) = \'42\' then \'4XL\' WHEN upper(split_part(a.sku,\'-\',-1)) = \'5XL\' OR upper(split_part(a.sku,\'-\',-1)) = \'44\' then \'5XL\' WHEN upper(split_part(a.sku,\'-\',-1)) = \'6XL\' OR upper(split_part(a.sku,\'-\',-1)) = \'46\' THEN \'6XL\' WHEN upper(split_part(a.sku,\'-\',-1)) = \'7XL\' OR upper(split_part(a.sku,\'-\',-1)) = \'48\' THEN \'7XL\' WHEN upper(split_part(a.sku,\'-\',-1)) = \'8XL\' OR upper(split_part(a.sku,\'-\',-1)) = \'48\' THEN \'8XL\' end as size, b.product_type as category, b.product_tags as product_tags, c.original_price as price, d.cost_price, MARKETPLACE_MAPPED AS channel, SUM(NULLIF(selling_price, 0)) AS gross_sales, SUM(NULLIF(shipping_quantity, 0)) AS gross_quantity, sum(shipping_quantity*c.original_price - selling_price) as discount_amount, SUM(CASE WHEN new_customer_flag != \'Repeated\' THEN selling_price ELSE 0 END) AS new_customers_revenue, SUM(CASE WHEN new_customer_flag = \'Repeated\' THEN selling_price ELSE 0 END) AS repeat_customers_revenue, COUNT(DISTINCT CASE WHEN new_customer_flag != \'Repeated\' THEN phone ELSE NULL END) AS new_customers FROM snitch_db.maplemonk.STORE_fact_items_offline a left join metafields b on a.sku_group = b.sku_group LEFT JOIN final_price c ON a.sku_group = c.sku_group left join cost_price d on a.sku = d.sku where marketplace_mapped not like \'%- WH -%\' and lower(a.sku_group) not like \'cb%\' GROUP BY 1, 2, 3, 4, 5, 6, 7, 8, 9 ), main_data2 as ( select * from shopify_sales union all select * from marketplace_data union all select * from stores_data ), metafields_data as ( select sku_group, occassion_new, print_design, collar_new, material_new, sleeve_type, fit, color, closure, style from snitch_db.maplemonk.metafields_data ), class as ( select sku_group, sku_class from snitch_db.maplemonk.availability_master_v2 qualify row_number() over (partition by sku_group order by status desc) = 1 ), sku_group_distinct as ( select a.*, b.occassion_new, b.print_design, b.collar_new, b.material_new, b.sleeve_type, b.fit, b.color, b.closure, b.style, c.sku_class from main_data2 a left join metafields_data b on a.sku_group = b.sku_group left join class c on a.sku_group = c.sku_group ), unique_shopify as ( select distinct date, sku_group, 1 as shopify_unique from main_data2 where type = \'Shopify\' and gross_quantity > 0 ), unique_store as ( select distinct date, sku_group, 1 as store_unique from main_data2 where type = \'Store\' and gross_quantity > 0 ) select a.*, case when shopify_unique = 1 AND store_unique = 1 THEN \'SHOPIFY-STORE\' WHEN shopify_unique = 1 THEN \'SHOPIFY\' WHEN STORE_unique = 1 THEN \'STORE\' else null end as store_shopify_common from sku_group_distinct a left join unique_shopify b on a.date = b.date and a.sku_group = b.sku_group left join unique_store c on a.date = c.date and a.sku_group = c.sku_group ); create or replace table snitch_db.maplemonk.l1_category_horizontal_sales as ( WITH base_sales AS ( SELECT UPPER(TRIM(sku_group)) AS sku_group, type, date, SUM(gross_quantity) AS gross_quantity, SUM(gross_sales) AS gross_sales FROM snitch_db.maplemonk.horizontal_sales_categories GROUP BY 1, 2, 3 ), l1_category_deduped AS ( SELECT sku_group, MAX(l1_category) AS l1_category, MAX(category) AS category, MAX(branch_name_final) AS branch_name_final FROM snitch_db.maplemonk.category_journey GROUP BY sku_group ) SELECT a.sku_group, a.type, a.date, b.category, a.gross_quantity, a.gross_sales, b.l1_category, b.branch_name_final, CASE WHEN LOWER(b.category) IN (\'sweaters\',\'sweatshirts\',\'jackets\',\'hoodies\') THEN \'core_winter\' ELSE \'non_core_winter\' END AS core_winter_mapped, CASE WHEN LOWER(b.category) IN (\'sweaters\',\'sweatshirts\',\'jackets\',\'hoodies\',\'overshirt\') THEN \'winter\' ELSE \'non_winter\' END AS winter_mapped FROM base_sales a LEFT JOIN l1_category_deduped b ON a.sku_group = b.sku_group ); create or replace table snitch_db.maplemonk.affiliate_sales_cost_source as ( select order_date, partner_af, source_af, sum(cost) as cost, sum(sales) as sales, sum(discount) as discount, (sum(discount)/sum(discount+sales))*100 as discount_percentage from snitch_db.maplemonk.affiliate_snitch group by 1,2,3 ); create or replace table snitch_db.maplemonk.cotton_sales_inv_mix as with sales as ( select date as order_date, sum(case when lower(material_new) like \'%cotton%\' then gross_quantity end) as cotton_qty, sum(gross_quantity) as total_quant from horizontal_sales_categories group by 1 ), cotton_sku as ( select sku_group from metafields_data where lower(material_new) like \'%cotton%\' ), inv as ( select date as order_date, sum(case when sku_group in (select sku_group from cotton_sku) then total_inventory end) as cotton_inv, sum(total_inventory) as total_inv from cut_size_analysis group by 1 ) select a.*, b.cotton_inv, b.total_inv from sales a left join inv b on a.order_date = b.order_date ;",
